import json
from collections import Counter
from pathlib import Path
from django.core.management.base import BaseCommand
from monitor.catalog import MAPPING,territory_kind
from monitor.sdmx import unpack_uploads
class Command(BaseCommand):
    help='Полное исследование всех XML и сохранение отчётов JSON/Markdown'
    def add_arguments(self,parser):
        parser.add_argument('archive');parser.add_argument('--output',default='docs')
    def handle(self,*args,**options):
        p=Path(options['archive']);docs=unpack_uploads([(p.name,p.read_bytes())]);out=Path(options['output']);out.mkdir(parents=True,exist_ok=True)
        records=[];text=['# Исследование исходных данных','', 'Исследованы все узлы всех шести выгрузок. Числа ниже рассчитаны по наблюдениям, а не по DataRange или Prepared. Названия, методики и организации взяты из XML.','']
        for d in docs:
            territories={r['territory']:r['territory_name'] for r in d.rows}
            unique={(r['territory'],r['period'],r['dimension_key']) for r in d.rows}
            samples=[{'territory':r['territory'],'period':r['period'],'dimensions':r['dimensions'],'raw_value':r['raw_value']} for r in (d.rows[0],d.rows[len(d.rows)//2],d.rows[-1])]
            rec={'file':d.filename,'program':MAPPING.get(d.file_id),'file_id':d.file_id,'indicator_metadata_id':d.metadata_id,'header_id':d.header_id,'dataset_id':d.dataset_id,'name':d.name,'unit':d.unit,'periods':d.periods,'territories':d.territories,'territory_levels':dict(Counter(territory_kind(c,n) for c,n in territories.items())),'series':d.series_count,'observations':len(d.rows),'unique_observations':len(unique),'sha256':d.sha256,'size':len(d.content),'metadata':d.metadata,'codelists':d.codelists,'dimension_names':d.dimension_names,'samples':samples}
            records.append(rec)
            text += [f'## {d.filename} — {d.name}','',f'Программа: {rec["program"]}. Файл ID {d.file_id}; Indicator/@id {d.metadata_id}; Header/ID {d.header_id}; DataSetID {d.dataset_id}.',f'Единица: {d.unit}. {d.metadata["unit_multiplier"]}',f'Методика: {d.metadata["methodology"]}',f'Организация: {d.metadata["organization"]}; подразделение: {d.metadata["department"]}.',f'Формы: {json.dumps(d.metadata["forms"],ensure_ascii=False) if d.metadata["forms"] else "Отдельный узел Forms отсутствует. Для 43587 форма 2-наука упомянута внутри Methodology."}',f'Подготовлено: {d.metadata["prepared"]}. Это дата выгрузки, а не период статистики.',f'Периоды: {", ".join(d.periods)}.',f'Территорий с наблюдениями: {d.territories}; рядов Series: {d.series_count}; наблюдений Obs: {len(d.rows)}; уникальных ключей: {len(unique)}.',f'Уровни территорий: {json.dumps(rec["territory_levels"],ensure_ascii=False)}.',f'Значения дополнительных измерений: {json.dumps(d.metadata["dimension_values"],ensure_ascii=False)}.',f'Атрибуты: {json.dumps(d.metadata["attributes"],ensure_ascii=False)}.',f'Явных пропусков / специальных значений: {d.metadata["missing"]}; одинаковых дубликатов: {d.metadata["duplicates"]}.',f'Комментарий источника: {d.metadata["comment"]}',f'SHA-256: `{d.sha256}`.','', 'Контрольные примеры:', '```json',json.dumps(samples,ensure_ascii=False,indent=2),'```','']
        text+=['## Общие выводы','',f'Всего наблюдений: {sum(len(d.rows) for d in docs)}. Все шесть корней GenericData относятся к SDMX 1.0. Каждый Series в данном наборе содержит одно Obs. Справочники могут содержать неиспользуемые коды: число территорий посчитано по фактическим рядам.','', 'В 44198 время включает 2014 и 2015 годы, а PERIOD принимает I, II и III квартал. Получены шесть квартальных периодов. s_OKFS: 200, 12, 13, 14. Код 199 присутствует в справочнике, но отсутствует в наблюдениях. Периоды кварталов не складываются и автоматически не трактуются как нарастающий итог.','', 'Все предоставленные ObsValue числовые, включая значения с десятичной запятой. Отсутствующие сочетания территории, периода и измерений не образуют записей и не превращаются в нули. Возможность явных пропусков и статусов проверяется на производных тестовых XML, не подмешиваемых в сдаваемую базу.','', 'В явном виде UNIT_MULT отсутствует во всех шести файлах. Слово «миллион» в EI показателя 43537 уже задаёт масштаб. Импорт не умножает исходные значения повторно.','', 'Классификация уровней опирается на названия и структуру кодов данного набора. У справочника нет надёжной иерархии родителей и исторического версионирования. Сохраняются исходные коды, в том числе 030, 643004.АГ и 15009.АГ. Аналитические суммы по территориям не рассчитываются.','']
        (out/'data_research.json').write_text(json.dumps(records,ensure_ascii=False,indent=2),encoding='utf-8')
        (out/'data_research.md').write_text('\n'.join(text),encoding='utf-8');self.stdout.write(f'Отчёты: {out}; наблюдений {sum(len(d.rows) for d in docs)}')
